// Des: Read a PDF ToUnicode CMap and map font codes to text
// Flo: find codespace width > parse bfchar and bfrange blocks > code to UTF-8 map > decode byte strings
// I/O: CMap stream bytes (caller) > Cmap (code width, map); decode(bytes) appends UTF-8
// ===================================================================
const std = @import("std"); const mem = std.mem; const obje = @import("pa-pdfz-obje.zig");
const CF = .{ .entz = 120000, .rngz = 65535 };
pub const Cmap = struct { cswz: u8 = 0, map: std.AutoHashMapUnmanaged(u32, []const u8) = .empty };
fn hexNext(src: []const u8, ix: *usize) ?[]const u8 { var kix = ix.*; while (kix < src.len and src[kix] != '<') { if (src[kix] == 'e' and mem.startsWith(u8, src[kix..], "end")) return null; kix += 1; } if (kix >= src.len) return null; const clo = mem.findScalarPos(u8, src, kix, '>') orelse return null; const txt = src[kix + 1 .. clo]; ix.* = clo + 1; return txt; }
fn hexNum(txt: []const u8) u32 { var val: u32 = 0; for (txt) |chr| { const dig = std.fmt.charToDigit(chr, 16) catch continue; val = (val << 4) | dig; } return val; }
fn uniEnc(aren: std.mem.Allocator, txt: []const u8, add: u32) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var units: [16]u16 = undefined; var cnt: usize = 0; var kix: usize = 0; if (txt.len <= 2) { units[0] = @intCast(hexNum(txt) + add); cnt = 1; } else { while (kix + 4 <= txt.len and cnt < units.len) : (kix += 4) { units[cnt] = @intCast(hexNum(txt[kix .. kix + 4])); cnt += 1; } if (add != 0 and cnt > 0) units[cnt - 1] +%= @intCast(add); } var idx: usize = 0; while (idx < cnt) : (idx += 1) { var cpt: u21 = units[idx]; if (cpt >= 0xD800 and cpt < 0xDC00 and idx + 1 < cnt) { const lo = units[idx + 1]; cpt = 0x10000 + ((cpt - 0xD800) << 10) + (lo - 0xDC00); idx += 1; } var buf: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(cpt, &buf) catch continue; try outp.appendSlice(aren, buf[0..lenz]); } return outp.toOwnedSlice(aren); }
pub fn cmapParse(aren: std.mem.Allocator, src: []const u8) !Cmap { var cmp: Cmap = .{}; if (mem.find(u8, src, "begincodespacerange")) |cs0| { var cix = cs0; if (hexNext(src, &cix)) |lo| cmp.cswz = @intCast(@min(@max(lo.len / 2, 1), 2)); } var kix: usize = 0; while (mem.findPos(u8, src, kix, "beginbfchar")) |bst| { const ben = mem.findPos(u8, src, bst, "endbfchar") orelse src.len; kix = bst + 11; while (cmp.map.count() < CF.entz) { const sct = hexNext(src[0..ben], &kix) orelse break; const dst = hexNext(src[0..ben], &kix) orelse break; try cmp.map.put(aren, hexNum(sct), try uniEnc(aren, dst, 0)); } kix = ben; } kix = 0; while (mem.findPos(u8, src, kix, "beginbfrange")) |bst| { const ben = mem.findPos(u8, src, bst, "endbfrange") orelse src.len; kix = bst + 12; const sub = src[0..ben]; while (cmp.map.count() < CF.entz) { const lot = hexNext(sub, &kix) orelse break; const lo = hexNum(lot); const hit = hexNext(sub, &kix) orelse break; const hi = hexNum(hit); if (hi < lo or hi - lo > CF.rngz) break; const nxt = obje.skipWs(sub, kix); if (nxt < sub.len and sub[nxt] == '[') { kix = nxt + 1; var cod = lo; while (cod <= hi) : (cod += 1) { const dtx = hexNext(sub, &kix) orelse break; try cmp.map.put(aren, cod, try uniEnc(aren, dtx, 0)); } const clo = mem.findScalarPos(u8, sub, kix, ']') orelse sub.len; kix = clo + 1; } else { const dtx = hexNext(sub, &kix) orelse break; var cod = lo; while (cod <= hi and cmp.map.count() < CF.entz) : (cod += 1) try cmp.map.put(aren, cod, try uniEnc(aren, dtx, cod - lo)); } } kix = ben; } return cmp; }
pub fn cmapDeco(cmp: Cmap, aren: std.mem.Allocator, byts: []const u8, outp: *std.ArrayList(u8), cswz: u8) !u32 { var hit: u32 = 0; var kix: usize = 0; while (kix < byts.len) { var cod: u32 = byts[kix]; var stp: usize = 1; if (cswz == 2 and kix + 1 < byts.len) { cod = (@as(u32, byts[kix]) << 8) | byts[kix + 1]; stp = 2; } kix += stp; if (cmp.map.get(cod)) |txt| { try outp.appendSlice(aren, txt); hit += 1; } } return hit; }
